let a = 30;

function setup() {
  createCanvas(640, 640);
  noStroke();
  fill(0, 255, 150);
}

function draw() {
  background(40);
  translate(width/2-25, height/2);
  for (let i = 0; i < 360; i+=(Math.max(0.001, Math.abs(a)) || 1)) {
    for(let q = -36; q < 36; q++){
      let x = i/(a/6)+tan(radians(dist(i/(a/2), i/(a/2), 0, 0)+q*50+frameCount))*a;
      ellipse(x, q*10, 5, 5); 
    }
  }
}
